import React, { useState, useEffect } from "react";
import { Plus } from "lucide-react";
import axios from "axios";

import JobStats from "../components/JobStats";
import JobTable from "../components/JobTable";
import JobForm from "../components/JobForm";
import ApplicationsTable from "../components/ApplicationsTable";

function JobAdminPage() {
  const [jobs,setJobs] = useState([]);
  const [applications,setApplications] = useState([]);
  const [isFormOpen,setIsFormOpen] = useState(false);
  const [editingJob,setEditingJob] = useState(null);
  const [activeTab,setActiveTab] = useState("jobs");

  useEffect(()=>{
    fetchJobs();
    fetchApplications();
  },[]);

  const fetchJobs = async ()=>{
    try { const res = await axios.get("http://localhost:5000/api/jobs"); setJobs(res.data); }
    catch(err){ console.error(err); alert("Failed to fetch jobs"); }
  }

  const fetchApplications = async ()=>{
    try { const res = await axios.get("http://localhost:5000/api/applications"); setApplications(res.data); }
    catch(err){ console.error(err); alert("Failed to fetch applications"); }
  }

  const addOrUpdateJob = async (jobData)=>{
    const payload = {
      ...jobData,
      createdAt: new Date().toLocaleDateString(),
      department: jobData.department||"NA",
      responsibilities: jobData.responsibilities||"NA",
      qualifications: jobData.qualifications||"NA",
      benefits: jobData.benefits||"NA",
      deadline: jobData.deadline||"NA",
    };

    try{
      if(editingJob){
        const res = await axios.put(`http://localhost:5000/api/jobs/${editingJob._id}`, payload);
        setJobs(jobs.map(j=>j._id===editingJob._id ? res.data : j));
        setEditingJob(null);
        alert("Job updated successfully");
      } else {
        const res = await axios.post("http://localhost:5000/api/jobs", payload);
        setJobs([...jobs,res.data]);
        alert("Job added successfully");
      }
      setIsFormOpen(false);
    } catch(err){
      console.error("Error adding/updating job:", err.response||err);
      alert("Failed to add/update job. Check console.");
    }
  };

  const handleEdit = (job)=>{ setEditingJob(job); setIsFormOpen(true); };
  const handleDelete = async (_id)=>{
    if(!window.confirm("Delete this job?")) return;
    try{ await axios.delete(`http://localhost:5000/api/jobs/${_id}`);
    setJobs(jobs.filter(j=>j._id!==_id)); alert("Deleted"); }
    catch(err){ console.error(err); alert("Failed to delete job"); }
  };

  return (
    <div style={{padding:"40px",background:"#f5f7fb"}}>
      <div style={{maxWidth:"1200px",margin:"0 auto"}}>
        <div style={{display:"flex",justifyContent:"space-between",marginBottom:"20px"}}>
          <h1>Job Administration</h1>
          {activeTab==="jobs" && <button onClick={()=>setIsFormOpen(true)}><Plus/> Add Job</button>}
        </div>

        <div style={{display:"flex",gap:"20px",marginBottom:"20px"}}>
          <div onClick={()=>setActiveTab("jobs")} style={{padding:"10px",cursor:"pointer",background:activeTab==="jobs"?"#2563eb":"#fff",color:activeTab==="jobs"?"#fff":"#000"}}>Jobs</div>
          <div onClick={()=>setActiveTab("applications")} style={{padding:"10px",cursor:"pointer",background:activeTab==="applications"?"#2563eb":"#fff",color:activeTab==="applications"?"#fff":"#000"}}>Applications</div>
        </div>

        {activeTab==="jobs" ? <>
          <JobStats jobs={jobs}/>
          <JobTable jobs={jobs} onEdit={handleEdit} onDelete={handleDelete}/>
        </> : <ApplicationsTable applications={applications}/>}

        {isFormOpen && <JobForm job={editingJob} onClose={()=>setIsFormOpen(false)} onSubmit={addOrUpdateJob}/>}
      </div>
    </div>
  );
}

export default JobAdminPage;
